// Resolves imports inside apps/web/src/v1 through the alias map scripts/v1-lift.py writes (src/v1/aliases.json) plus the
// hand-written seam answers for npm modules (src/v1/seam/npm-aliases.json), so lifted v1 files stay byte-identical
// (devlog 070 Revision A2). Only importers under src/v1 are aliased: GOAT 2 code keeps the real packages (e.g.
// @base-ui/react/popover without the v1 portal root) and reaches v1 only through @v1/surfaces. tsconfig.v1.paths.json
// carries the same map as TypeScript paths, generated by the same script.
import { readFileSync } from "node:fs";
import path from "node:path";
import type { Plugin } from "vite";

export function v1Aliases(webRoot: string): Plugin {
  const repoRoot = path.resolve(webRoot, "../..");
  const v1Dir = path.join(webRoot, "src", "v1") + path.sep;
  const mapFile = path.join(v1Dir, "aliases.json");
  const npmFile = path.join(v1Dir, "seam", "npm-aliases.json");
  let map: Record<string, string> = {};
  const load = () => {
    const npm = JSON.parse(readFileSync(npmFile, "utf8")) as Record<string, string>;
    delete npm["//"];
    map = { ...(JSON.parse(readFileSync(mapFile, "utf8")) as Record<string, string>), ...npm };
  };
  load();
  return {
    name: "goat2-v1-aliases",
    enforce: "pre",
    configureServer(server) {
      server.watcher.add([mapFile, npmFile]);
      server.watcher.on("change", (f) => { if ([mapFile, npmFile].includes(path.resolve(f))) load(); });
    },
    async resolveId(source, importer, options) {
      if (source === "@v1/surfaces") return path.join(v1Dir, "seam", "goat2", "surfaces.ts");
      if (!importer || !importer.split("?")[0]!.startsWith(v1Dir)) return null;
      let target: string | undefined;
      if (source.startsWith("~/")) target = path.join(repoRoot, map["~"]!, source.slice(2));
      else if (map[source] !== undefined) target = path.join(repoRoot, map[source]!);
      if (target === undefined) return null;
      return this.resolve(target, importer, { ...options, skipSelf: true });
    },
  };
}
